mapper.insert:
INSERT INTO runtime_hold (tenant_id, scope, scope_id, kind, reason, held_by)
SELECT #{tenantId}, #{scope}, #{scopeId}, #{kind}, #{reason}, #{by}
WHERE NOT EXISTS (
    SELECT 1 FROM runtime_hold
     WHERE tenant_id = #{tenantId} AND scope = #{scope}
       AND COALESCE(scope_id, 0) = COALESCE(CAST(#{scopeId} AS bigint), 0)
       AND kind = #{kind}
       AND released_at IS NULL
)

